import { writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { agentApiVersion, agentOperations } from '../src/agent-api/capabilities.ts';

type DocumentedOperation = Readonly<{
  id: string;
  method: string;
  path: string;
  scope: string;
  description: string;
}>;

export function renderAgentOperations(operations: readonly DocumentedOperation[] = agentOperations): string {
  const lines = [
    '<!-- Generated by scripts/agent-skill-reference.ts. Update the registry and regenerate. -->',
    '',
    '# LifeOS Agent API operations',
    '',
    `API version \`${agentApiVersion}\`.`,
    '',
    '| ID | Method | Path | Scope | Purpose |',
    '| --- | --- | --- | --- | --- |',
    ...operations.map(({ id, method, path, scope, description }) =>
      `| \`${id}\` | \`${method}\` | \`${path}\` | \`${scope}\` | ${description.replaceAll('|', '\\|').replace(/\r?\n/g, ' ')} |`),
    '',
  ];
  return lines.join('\n');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  writeFileSync(new URL('../skills/lifeos-agent/references/operations.md', import.meta.url), renderAgentOperations());
}
